#!/usr/bin/env bash
# Ms. Codex 1508 - [Ledger of Medici debtors and creditors and accounts] (UPenn), 235 images, full/max JPEGs
# Filenames: SEQ_fOLD_mMODERN  (old = inked foliation, modern = bracketed [=..] foliation in the manifest)
# Not photographed (per manifest): 113v through back flyleaf 1 recto (blank).
set -u
OUT="${1:-MsCodex1508}"; mkdir -p "$OUT"
dl() { local f="$OUT/$1.jpg"; [ -s "$f" ] && return; curl -fsS --retry 5 --retry-delay 5 -o "$f.part" "$2" && mv "$f.part" "$f" && echo "ok  $1" || echo "FAIL $1"; sleep 1; }
